    if [ "$f1a" = 3 ] && [ ! -s "$ntmp/f1a.s" ] && grep -q "expects 2 argument" "$ntmp/f1a.err"; then ok "phase-2 F1: wrong constructor arity is a clear type error"; else bad "phase-2 F1: wrong constructor arity is a clear type error"; fi
