if ../../lume agent eval ../../compiler/stage1/compiler_effects_ok.src 2>/dev/null | grep -q '"result":"108\\n244"'; then ok "inflection Stage C: cross-platform CompilerIO driver effect & / pure pipeline passes"; else bad "inflection Stage C: cross-platform CompilerIO driver effect & / pure pipeline passes"; fi

_sd_tmp=$(mktemp)
printf 'fn isnil(xs) = match xs\n    Nil => 1\n    Cons(h, t) => 0\nfn pairs(own xs) = match xs\n    Nil => Nil\n    Cons(a, t) => pairs2(a, own t)\nfn pairs2(a, own t) = match t\n    Nil => Cons(a, Nil)\n    Cons(b, r) => Cons(a + b, pairs(own r))\nfn joinall(own xs) = match xs\n    Nil => ""\n    Cons(a, t) => if isnil(t) == 1 then a else joinall(own pairs2(a, own t))\nfn geexpr(own e) = match e\n    Num(n) => Num(n + 10)\n    Bin(op, l, r) => Bin(op, geexpr(own l), geexpr(own r))\n    _ => e\nfn eval_e(e) = match e\n    Num(n) => n\n    Bin(op, l, r) => eval_e(l) + eval_e(r)\n    _ => 0\nprint joinall(own Cons("lume-", Cons("stage-", Cons("d", Nil))))\nprint eval_e(geexpr(own Bin("+", Num(15), Num(35))))\n' >"$_sd_tmp"
if ../../lume agent eval "$_sd_tmp" 2>/dev/null | grep -q '"result":"lume-stage-d\\n70"'; then ok "inflection Stage D: cross-platform Perceus own-annotated compiler passes (joinall, gerase, cfold)"; else bad "inflection Stage D: cross-platform Perceus own-annotated compiler passes"; fi
rm -f "$_sd_tmp"

_sb_all_tmp=$(mktemp)
printf 'fn f(x: int) -> int requires x >= 0 ensures result >= 0 = 10 - x\nfn h(x: int) -> int requires x >= 0 ensures result != 0 = x - 1000000\nfn g(x: int) -> int requires x >= 5 ensures result >= 1 = x - 4\nfn sq(x: int) -> int ensures result >= 0 = x * x\npub fn w(bal: int, amt: int) -> int requires bal >= amt requires amt >= 0 ensures result == bal - amt and result >= 0 = _\nprint g(6)\nprint sq(0 - 7)\n' >"$_sb_all_tmp"
_sb_all_out=$(../../lume prove --json "$_sb_all_tmp" 2>/dev/null || true)
if printf '%s' "$_sb_all_out" | grep -q '"name":"f","kind":"contract","status":"refuted"' && printf '%s' "$_sb_all_out" | grep -q '"counterexample":"x = 11 (result = -1)"' && printf '%s' "$_sb_all_out" | grep -q '"name":"h","kind":"contract","status":"refuted"' && printf '%s' "$_sb_all_out" | grep -q '"counterexample":"x = 1000000 (result = 0)"' && printf '%s' "$_sb_all_out" | grep -q '"name":"g","kind":"contract","status":"proven"' && printf '%s' "$_sb_all_out" | grep -q '"name":"sq","kind":"contract","status":"runtime_checked"' && printf '%s' "$_sb_all_out" | grep -q '"proven_candidates":\["bal - amt"\]'; then ok "inflection Stage B (#173 case 6) & docs/19 oracle: cross-platform QF_LIA soundness, hole synthesis & determinism (ubuntu + macOS + ASan/UBSan)"; else bad "inflection Stage B (#173 case 6) & docs/19 oracle: cross-platform QF_LIA soundness & hole synthesis"; printf '%s\n' "$_sb_all_out"; fi
rm -f "$_sb_all_tmp"

if [ "$(uname -s)" = "Linux" ] && [ "$(uname -m)" = "x86_64" ] && [ -z "${LUME0_ASAN:-}" ]; then
    _e1ok=$(../../lume compile --json --run ../../compiler/stage1/e1_sample.src 2>/dev/null)
    _e1bad=$(../../lume compile --json ../../compiler/stage1/e1_bad.src 2>/dev/null)
    if printf '%s' "$_e1ok" | grep -q '"ok":true' && printf '%s' "$_e1ok" | grep -q '"ran":true' && printf '%s' "$_e1ok" | grep -q '"run_exit":0' && printf '%s' "$_e1ok" | grep -q 'stdout":"42' && printf '%s' "$_e1bad" | grep -q '"ok":false' && printf '%s' "$_e1bad" | grep -q 'assertion failed'; then ok "phase-2 E1: lume compile --json emits a structured {ok, asm_lines, stdout} result and reports errors"; else bad "phase-2 E1: compile-as-a-service (lume compile --json)"; fi
else
    ok "phase-2 E1: compile-as-a-service (skipped: not linux/x86_64, or under ASan)"
fi

echo "== AI-first: `lume0 describe` emits valid JSON"
if command -v python3 >/dev/null 2>&1; then
    if $BIN describe | python3 -c 'import json,sys; json.load(sys.stdin)' 2>/dev/null; then ok "describe --json"; else bad "describe --json"; fi
fi

echo "== Lume-in-Lume: Stage-1 programs run under lume0"
for exp in ../../tests/conformance/stage1/*.expected; do
    [ -f "$exp" ] || continue
    base=$(basename "$exp" .expected)
    src="../../compiler/stage1/$base.lume"
    [ -f "$src" ] || continue    # expected files without a matching .lume (e.g. native-binary tests) are handled elsewhere
    if $BIN run "$src" 2>/dev/null | diff -u "$exp" - >/dev/null; then ok "compiler/stage1/$base.lume"; else bad "compiler/stage1/$base.lume"; $BIN run "$src" 2>/dev/null | diff -u "$exp" - | head -20; fi
done

echo "== LBE: emit to binary AST and run it with no re-parse (output must match text run)"
tmpd=$(mktemp -d)
for exp in ../../tests/conformance/stage0/*.expected; do
    [ -f "$exp" ] || continue
    base=$(basename "$exp" .expected)
    src="$EX/$base.lume"
    $BIN emit "$src" "$tmpd/$base.lbe" 2>/dev/null
    if $BIN run "$tmpd/$base.lbe" 2>/dev/null | diff -u "$exp" - >/dev/null; then ok "lbe $base"; else bad "lbe $base"; fi
done
rm -rf "$tmpd"

echo "== negative lexer cases"
for src in tests/lexer/bad_*.lume; do
    code=$(sed -n '1s/^# expect: //p' "$src")
    if $BIN check "$src" --json 2>/dev/null | grep -q "\"code\":\"$code\""; then ok "$src ($code)"; else bad "$src (expected $code)"; fi
done

echo "== negative parser cases"
for src in tests/parser/bad_*.lume; do
    [ -f "$src" ] || continue
    code=$(sed -n '1s/^# expect: //p' "$src")
    if $BIN check "$src" --json 2>/dev/null | grep -q "\"code\":\"$code\""; then ok "$src ($code)"; else bad "$src (expected $code)"; $BIN check "$src" --json; fi
done

echo "== resolve: undefined names are caught at check time"
for src in tests/resolve/bad_*.lume; do
    [ -f "$src" ] || continue
    code=$(sed -n '1s/^# expect: //p' "$src")
    if $BIN check "$src" --json 2>/dev/null | grep -q "\"code\":\"$code\""; then ok "$src ($code)"; else bad "$src (expected $code)"; $BIN check "$src" --json; fi
done
for src in tests/resolve/ok_*.lume; do
    [ -f "$src" ] || continue
    if $BIN check "$src" >/dev/null 2>e.txt; then ok "$src (clean)"; else bad "$src (should resolve clean)"; sed 's/^/      /' e.txt | head -4; fi
done

echo "== positive parser cases (must parse clean)"
for src in tests/parser/ok_*.lume; do
    [ -f "$src" ] || continue
    # parser ok-tests assert PARSING only (bare free identifiers are expected); use parse, not check
    if $BIN parse "$src" >/dev/null 2>e.txt; then ok "$src"; else bad "$src"; sed 's/^/      /' e.txt | head -4; fi
done

rm -f e.txt
echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
